-- Generated by scripts/generate-business-sql.mts from content/site.ts.
-- The business page upgrade: personal and business bundles with today's prices, the full process,
-- guarantees, case studies, the discovery-call agenda, add-ons and FAQ.
-- REPLACES every row on Studio's Business board. Run once in Supabase → SQL Editor.
begin;

delete from public.studio_items where board = 'business';


update public.studio_items
set data = data || $j${"tagline":"Your website gets visits. It should get you clients.","replyTime":"Replies personally, within 1 business day"}$j$::jsonb
where board = 'site' and group_key = 'profile';

update public.studio_items
set data = data || $j${"quote":"I had a picture in my head of what my website should be, and Chris made it real. Now I have one place to send when I apply for auditions, work and everything else."}$j$::jsonb
where board = 'site' and group_key = 'testimonials' and title = $t$Erwin Natividad$t$;

commit;
